#define DTMF_LENGTH_MAX  40

extern call_origin_e g_call_origin;

static lv_timer_t * dtmf_key_timer = NULL;
static lv_timer_t * slidervolume_timer = NULL;
static char s_str_dtmf[DTMF_LENGTH_MAX + 1] = {0};
static int s_dtmfstr_num = 0;

static lv_timer_t *calltime_timer = NULL;
static uint64_t g_tick_cnt = 0;

static void display_connected_phonenum(char *p_phone_num)
{
    if(NULL == p_phone_num) {
        LV_LOG_ERROR("[%s],p_phone_num is null",__func__);
        return;
    }
    lv_label_set_text(ui_LblConnectedPhoneNum, p_phone_num);
}

static void delete_calltime_timer(void)
{
    if(NULL != calltime_timer) {
        lv_timer_del(calltime_timer);
        calltime_timer = NULL;
        g_tick_cnt = 0;
    }
}
static void update_calltime(lv_timer_t * t)
{
    int hour = 0;
    int minute = 0;
    int sec = 0;
    int n = 0;

    char calltime[10] = {0};

    //n = (aic_get_tick() /1000) - g_tick_cnt;
    n = (lv_tick_get() /1000) - g_tick_cnt;

    hour = n/3600;
    n = n % 3600;
    minute = n/60;
    sec = n%60;

    sprintf(calltime,"%02d:%02d:%02d",hour,minute,sec);

    lv_label_set_text(ui_LblDuration,calltime);

}

static void display_calltime(void)
{
    calltime_timer = lv_timer_create(update_calltime, 1000, NULL);
    lv_timer_set_repeat_count(calltime_timer,-1);
    //g_tick_cnt = aic_get_tick()/1000;
    g_tick_cnt = lv_tick_get()/1000;
}

static void dtmf_key_timer_event(lv_timer_t * t)
{
    lv_timer_pause(dtmf_key_timer);
    call_flow_send_dtmf(s_str_dtmf);
    s_dtmfstr_num = 0;
    memset(s_str_dtmf,0,(DTMF_LENGTH_MAX + 1));
}

static void slidervolume_timer_event(lv_timer_t * t)
{
    LV_LOG_USER("[key test] slidervolume_timer pause");
    lv_timer_pause(slidervolume_timer);
    lv_obj_add_flag(ui_SliderVolume, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(ui_ImgVolume, LV_OBJ_FLAG_HIDDEN);
}

void connected_win_active(lv_obj_t *win, void *p_param)
{
    //char num[CALL_PHONE_NUMBER_LEN_MAX] = {0};
    char *p_phone_num = NULL;
    uint32_t volume = 0;

    ui_connected_init();
    /* get system volume value and set volume bar*/
    volume = call_flow_get_call_volume();
    lv_slider_set_value(ui_SliderVolume,volume,LV_ANIM_OFF);
    /* display phone number */
    //call_flow_get_phonenum(num);
    if(NULL != p_param) {
        p_phone_num = (char *)p_param;
        LV_LOG_USER("[%s],phone number is %s", __func__, p_phone_num);
    }
    display_connected_phonenum(p_phone_num);
    /* display call duaration */
    display_calltime();

    lv_group_add_obj(lv_group_get_default(), ui_Connected);
}

void connected_win_deactive(lv_obj_t *win, void *p_param)
{
    call_status_e current_call_status = call_flow_get_call_status();

    lv_obj_del(ui_Connected);
    delete_calltime_timer();
    if (NULL != dtmf_key_timer) {
        lv_timer_del(dtmf_key_timer);
        LV_LOG_USER("[key test] del dtmf_key_timer");
        dtmf_key_timer = NULL;
    }
    if (NULL != slidervolume_timer) {
        lv_timer_del(slidervolume_timer);
        LV_LOG_USER("[key test] del slidervolume_timer");
        slidervolume_timer = NULL;
    }

    LV_LOG_INFO("[%s], g_call_origin = %d,s_call_info.call_status = %d", __func__, g_call_origin, s_call_info.call_status);
    if(CALL_ORIGIN_GLOBAL_INCOMING == g_call_origin
        && current_call_status == CALL_STATUS_RELEASED) {
        alv_am_app_exit(NULL, "call", NULL);
    }
}
void connected_win_focus(lv_obj_t *win, void *p_param)
{
    lv_disp_load_scr(ui_Connected);
    lv_group_focus_obj(ui_Connected);
    /* display statusbar */
    SHOW_STATUSBAR;
}
